/** Packaged UI only. Google access tokens never enter the WebView. */
public class MainActivity extends ComponentActivity {
    private static final String ORIGIN="https://appassets.androidplatform.net";
    private static final String PAGE=ORIGIN+"/assets/index.html";
    private final ExecutorService io=Executors.newSingleThreadExecutor();
    private final ArrayDeque<Request> queue=new ArrayDeque<>();
    private final Set<String> actions=new HashSet<>(Arrays.asList("load","mutate","allocate","runRecurring","upload","file","export","backup","deleteFile"));
    private WebView web;
    private Request active;
    private ValueCallback<Uri[]> fileCallback;
    private String exportText;
    private boolean destroyed;
    private String selectedAccount;
    private final ActivityResultLauncher<IntentSenderRequest> authorizeResult=registerForActivityResult(
        new ActivityResultContracts.StartIntentSenderForResult(),result->{
            try { execute(Identity.getAuthorizationClient(this).getAuthorizationResultFromIntent(result.getData())); }
            catch(Exception e){ failActive("ไม่ได้รับสิทธิ์ Google กรุณาลองอีกครั้ง"); }
        });
    private final ActivityResultLauncher<Intent> chooseFile=registerForActivityResult(
        new ActivityResultContracts.StartActivityForResult(),result->{
            if(fileCallback!=null){fileCallback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result.getResultCode(),result.getData()));fileCallback=null;}
        });
    private final ActivityResultLauncher<Intent> exportFile=registerForActivityResult(
        new ActivityResultContracts.StartActivityForResult(),result->{
            String text=exportText;exportText=null;
            if(result.getResultCode()!=RESULT_OK||result.getData()==null||text==null)return;
            Uri uri=result.getData().getData();
            io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){
                if(out==null)throw new IOException();out.write(text.getBytes(StandardCharsets.UTF_8));notice("ส่งออกไฟล์แล้ว");
            }catch(Exception e){notice("ส่งออกไม่สำเร็จ กรุณาลองใหม่");}});
        });

    @Override public void onCreate(Bundle savedInstanceState){
        super.onCreate(savedInstanceState);
        getWindow().setStatusBarColor(0xff0c1930);getWindow().setNavigationBarColor(0xff0c1930);
        LinearLayout intro=new LinearLayout(this);intro.setOrientation(LinearLayout.VERTICAL);intro.setPadding(40,80,40,40);intro.setBackgroundColor(0xff0c1930);
        TextView title=new TextView(this);title.setText("💰 บัญชีรายเดือน");title.setTextSize(28);title.setTextColor(0xffffdf86);intro.addView(title);
        TextView detail=new TextView(this);detail.setTextColor(0xffe8ecf5);detail.setTextSize(17);detail.setPadding(0,36,0,36);
        boolean configured=!BuildConfig.API_DEPLOYMENT_ID.isEmpty();
        detail.setText(configured?"ใช้บัญชี Google ของคุณเพื่อเปิดข้อมูลใน Sheets และ Drive ส่วนตัว\n\nต้องเชื่อมต่ออินเทอร์เน็ต รุ่นทดสอบยังไม่มีการแจ้งเตือนเมื่อปิดแอป":"รุ่นทดสอบ: ยังไม่ได้ตั้งค่า API executable และ Android OAuth\n\nผู้พัฒนาต้องตั้งค่าการเชื่อมต่อ Google ก่อนใช้งานข้อมูลจริง");intro.addView(detail);
        Button start=new Button(this);start.setText("ดำเนินการต่อด้วย Google");start.setEnabled(configured);start.setOnClickListener(v->openApp());intro.addView(start);setContentView(intro);
        getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){@Override public void handleOnBackPressed(){
            if(web==null){finish();return;}web.evaluateJavascript("document.getElementById('modal').open",value->{
                if("true".equals(value))web.evaluateJavascript("document.getElementById('modal').close()",null);
                else new AlertDialog.Builder(MainActivity.this).setMessage("ออกจากแอป?").setPositiveButton("ออก",(d,w)->finish()).setNegativeButton("อยู่ต่อ",null).show();
            });
        }});
    }

    @SuppressWarnings("SetJavaScriptEnabled")
    private void openApp(){
        web=new WebView(this);web.setBackgroundColor(0xff0c1930);
        WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setCacheMode(WebSettings.LOAD_NO_CACHE);s.setJavaScriptCanOpenWindowsAutomatically(false);
        CookieManager.getInstance().setAcceptCookie(false);
        WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();
        web.setWebViewClient(new WebViewClient(){
            @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){
                Uri u=r.getUrl();if("https".equals(u.getScheme())&&"appassets.androidplatform.net".equals(u.getHost()))return loader.shouldInterceptRequest(u);
                return new WebResourceResponse("text/plain","UTF-8",403,"Blocked",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));
            }
            @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){
                if(PAGE.equals(r.getUrl().toString()))return false;
                if(r.isForMainFrame()&&r.hasGesture())openExternal(r.getUrl());return true;
            }
        });
        web.setWebChromeClient(new WebChromeClient(){
            @Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){
                if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;
                Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);
                try{chooseFile.launch(pick);}catch(Exception e){fileCallback.onReceiveValue(null);fileCallback=null;}return true;
            }
            @Override public boolean onJsConfirm(WebView v,String url,String message,JsResult result){
                new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("ยืนยัน",(d,w)->result.confirm()).setNegativeButton("ยกเลิก",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;
            }
            @Override public boolean onJsAlert(WebView v,String url,String message,JsResult result){
                new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("ตกลง",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;
            }
        });
        web.addJavascriptInterface(new Bridge(),"FinanceNative");
        // Insets remain outside the document to keep controls above system navigation.
        web.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        setContentView(web);web.loadUrl(PAGE);
    }
    private void openExternal(Uri u){
        String host=u.getHost();if(!"https".equals(u.getScheme())||!("docs.google.com".equals(host)||"drive.google.com".equals(host)||"script.google.com".equals(host)))return;
        try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){notice("ไม่พบเบราว์เซอร์สำหรับเปิดลิงก์");}
    }
    public final class Bridge {
        @JavascriptInterface public void request(String id,String action,String payload){
            if(id==null||!id.matches("[0-9]{1,12}"))return;
            if(!actions.contains(action)||payload==null||payload.length()>12_000_000){reply(id,false,"คำขอไม่ถูกต้อง");return;}
            try{JSONObject body=new JSONObject(payload);runOnUiThread(()->{
                if(!"load".equals(action)&&selectedAccount==null){reply(id,false,"กรุณาโหลดบัญชีให้เสร็จก่อน");return;}
                if(queue.size()>20){reply(id,false,"มีคำขอมากเกินไป กรุณารอสักครู่");return;}queue.add(new Request(id,action,body));next();
            });}catch(Exception e){reply(id,false,"ข้อมูลคำขอไม่ถูกต้อง");}
        }
        @JavascriptInterface public void exportDocument(String name,String text,String type){
            if(text==null||text.length()>20_000_000)return;
            runOnUiThread(()->{if(exportText!=null){notice("กรุณาบันทึกไฟล์ก่อนหน้าให้เสร็จก่อน");return;}exportText=text;
                Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(type!=null&&type.startsWith("text/csv")?"text/csv":"application/json").putExtra(Intent.EXTRA_TITLE,name!=null&&name.endsWith(".csv")?"transactions.csv":"monthly-finance.json");
                try{exportFile.launch(save);}catch(Exception e){exportText=null;notice("เปิดหน้าบันทึกไฟล์ไม่ได้");}
            });
        }
    }
    private record Request(String id,String action,JSONObject payload){}
    private void next(){
        if(destroyed||active!=null||queue.isEmpty())return;active=queue.remove();
        List<Scope> scopes=Arrays.asList(new Scope("https://www.googleapis.com/auth/spreadsheets"),new Scope("https://www.googleapis.com/auth/drive"),new Scope("https://www.googleapis.com/auth/script.scriptapp"),new Scope("https://www.googleapis.com/auth/userinfo.email"));
        AuthorizationRequest.Builder auth=AuthorizationRequest.builder().setRequestedScopes(scopes);
        if(selectedAccount!=null)auth.setAccount(new android.accounts.Account(selectedAccount,"com.google"));
        Identity.getAuthorizationClient(this).authorize(auth.build())
          .addOnSuccessListener(this,result->{
              if(result.hasResolution()){
                  try{authorizeResult.launch(new IntentSenderRequest.Builder(result.getPendingIntent().getIntentSender()).build());}
                  catch(Exception e){failActive("เปิดหน้าอนุญาต Google ไม่สำเร็จ");}
              }else execute(result);
          }).addOnFailureListener(this,e->failActive("เชื่อมบัญชี Google ไม่สำเร็จ ตรวจ Android OAuth และ SHA-1 ของ APK"));
    }
    private void execute(AuthorizationResult authorization){
        Request request=active;if(request==null)return;String token=authorization.getAccessToken();
        if(token==null||token.isEmpty()){failActive("ไม่ได้รับสิทธิ์ที่แอปต้องใช้");return;}
        io.execute(()->{
            HttpsURLConnection c=null;
            try {
                c=(HttpsURLConnection)new URL("https://script.googleapis.com/v1/scripts/"+BuildConfig.API_DEPLOYMENT_ID+":run").openConnection();
                c.setConnectTimeout(20000);c.setReadTimeout(380000);c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","application/json; charset=utf-8");
                JSONObject body=new JSONObject().put("function","androidApi").put("parameters",new JSONArray().put(request.action()).put(request.payload())).put("devMode",false);
                try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}
                int status=c.getResponseCode();
                InputStream stream=status>=200&&status<300?c.getInputStream():c.getErrorStream();
                if(stream==null)throw new IOException("ไม่มีการตอบกลับจาก Google");
                String json;try(stream;ByteArrayOutputStream buffer=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=stream.read(bytes))!=-1){if(buffer.size()+n>30_000_000)throw new IOException("ข้อมูลตอบกลับมีขนาดใหญ่เกินกำหนด");buffer.write(bytes,0,n);}json=buffer.toString("UTF-8");}
                JSONObject response=new JSONObject(json);
                if(status==401)Identity.getAuthorizationClient(MainActivity.this).clearToken(ClearTokenRequest.builder().setToken(token).build());
                if(response.has("error")){
                    JSONObject error=response.getJSONObject("error");String message=error.optString("message","Google ปฏิเสธคำขอ");JSONArray details=error.optJSONArray("details");
                    if(details!=null&&details.length()>0)message=details.getJSONObject(0).optString("errorMessage",message);
                    throw new IOException(message);
                }
                if(status<200||status>=300||!response.has("response"))throw new IOException("การเชื่อมต่อ Google ไม่สำเร็จ ("+status+")");
                Object result=response.getJSONObject("response").opt("result");
                if("load".equals(request.action())){
                    if(!(result instanceof JSONObject)||((JSONObject)result).optString("account").isEmpty())throw new IOException("ยืนยันบัญชีไม่ได้");
                    String email=((JSONObject)result).getString("account");
                    if(selectedAccount!=null&&!selectedAccount.equalsIgnoreCase(email))throw new IOException("บัญชีเปลี่ยน กรุณาปิดแอปแล้วเปิดใหม่");
                    // Set on the main thread before delivering the snapshot or running queued writes.
                    runOnUiThread(()->selectedAccount=email);
                }
                reply(request.id(),true,result);
            }catch(Exception e){reply(request.id(),false,"เชื่อมต่อไม่สำเร็จ: "+(e.getMessage()==null?"กรุณาลองใหม่":e.getMessage())+" — หากเป็นการบันทึก ให้โหลดข้อมูลก่อนลองซ้ำ");}
            finally{if(c!=null)c.disconnect();runOnUiThread(()->{active=null;next();});}
        });
    }
    private void failActive(String message){if(active!=null)reply(active.id(),false,message);active=null;next();}
    private void reply(String id,boolean ok,Object value){
        runOnUiThread(()->{if(!destroyed&&web!=null){String data=value instanceof JSONObject||value instanceof JSONArray?value.toString():value==null||value==JSONObject.NULL?"null":JSONObject.quote(String.valueOf(value));web.evaluateJavascript("window.androidReply("+JSONObject.quote(id)+","+ok+","+data+")",null);}});
    }
    private void notice(String text){runOnUiThread(()->{if(!destroyed)Toast.makeText(this,text,Toast.LENGTH_LONG).show();});}
    @Override protected void onDestroy(){destroyed=true;queue.clear();if(fileCallback!=null)fileCallback.onReceiveValue(null);if(web!=null){web.removeJavascriptInterface("FinanceNative");web.destroy();}io.shutdown();super.onDestroy();}
}

