/* บัญชีรายเดือน V2 — per-Google-user isolated storage. See README-TH.md. */
const TZ_='Asia/Bangkok';
function props_(){return PropertiesService.getUserProperties();}
function today_(){return Utilities.formatDate(new Date(),TZ_,'yyyy-MM-dd');}
function stamp_(){return new Date().toISOString();}
function identity_(){
  const active=Session.getActiveUser().getEmail(),effective=Session.getEffectiveUser().getEmail();
  if(!active||!effective||active.toLowerCase()!==effective.toLowerCase())fail_('กรุณาลงชื่อเข้าใช้ Google และตั้ง Deployment ให้รันเป็น User accessing the web app');
  return effective;
}
function owner_(){identity_();if(!props_().getProperty('READY'))fail_('ยังไม่พร้อมใช้งาน กรุณาโหลดหน้าใหม่เพื่อสร้างฐานข้อมูลของคุณ');}
// Explicit one-time migration: only the actual Drive owner can claim legacy data.
function migrateLegacyForOwner(){
  const email=identity_(),legacy=PropertiesService.getScriptProperties();
  const id=legacy.getProperty('SPREADSHEET_ID'),folder=legacy.getProperty('DRIVE_FOLDER_ID');
  if(!id||!folder)fail_('ไม่พบฐานข้อมูลเดิม');
  if(DriveApp.getFileById(id).getOwner().getEmail().toLowerCase()!==email.toLowerCase()||DriveApp.getFolderById(folder).getOwner().getEmail().toLowerCase()!==email.toLowerCase())fail_('เฉพาะเจ้าของไฟล์เดิมเท่านั้นที่ย้ายได้');
  return lock_(()=>{if(props_().getProperty('SPREADSHEET_ID')&&props_().getProperty('SPREADSHEET_ID')!==id)fail_('มีฐานข้อมูลใหม่แล้ว ไม่เขียนทับ');props_().setProperty('SPREADSHEET_ID',id);props_().setProperty('DRIVE_FOLDER_ID',folder);props_().setProperty('READY','1');return {migrated:true};});
}
function lock_(fn){const l=LockService.getUserLock();l.waitLock(30000);try{return fn();}finally{l.releaseLock();}}
let requestDb_,requestDbKey_;
function db_(){const id=props_().getProperty('SPREADSHEET_ID'),key=Session.getEffectiveUser().getEmail()+'|'+id;if(!id)fail_('กรุณารัน setup_ ใน Apps Script ก่อน');if(requestDb_&&requestDbKey_===key)return requestDb_;requestDbKey_=key;return requestDb_=SpreadsheetApp.openById(id);}
function setup_(){
  identity_();return lock_(()=>{
    let id=props_().getProperty('SPREADSHEET_ID');if(!id){const b=SpreadsheetApp.create('บัญชีรายเดือน • ฐานข้อมูลส่วนตัว');id=b.getId();props_().setProperty('SPREADSHEET_ID',id);}
    const b=SpreadsheetApp.openById(id); b.setSpreadsheetTimeZone(TZ_);
    TABLES_.concat(['AuditLog','Files']).forEach(name=>{let sh=b.getSheetByName(name);if(!sh){sh=b.insertSheet(name);sh.appendRow(name==='AuditLog'?['requestId','timestamp','changesJSON']:name==='Files'?['fileId','mime','purpose','createdAt']:['id','recordJSON','revision','updatedAt']);sh.setFrozenRows(1);}});
    if(!props_().getProperty('DRIVE_FOLDER_ID'))props_().setProperty('DRIVE_FOLDER_ID',DriveApp.createFolder('บัญชีรายเดือน • รูปและข้อมูลสำรอง').getId());
    const loaded=load_();if(!Object.keys(loaded.state.Categories).length){const changes=categories_().map(x=>({table:'Categories',id:x.id,value:Object.assign(x,{revision:1,updatedAt:stamp_()})}));changes.push({table:'Settings',id:'main',value:{id:'main',theme:'dark',notifyEnabled:true,revision:1,updatedAt:stamp_()}});commit_('setup-v2',changes,loaded);}
    sync_(load_().state);installTrigger_();props_().setProperty('READY','1');console.log('พร้อมใช้: https://docs.google.com/spreadsheets/d/'+id);return {spreadsheetId:id,ready:true};
  });
}
function installTrigger_(){
  if(androidInvocation_)return;
  if(ScriptApp.getProjectTriggers().some(t=>t.getHandlerFunction()==='recurringDaily_'))return;
  ScriptApp.newTrigger('recurringDaily_').timeBased().everyDays(1).atHour(6).inTimezone(TZ_).create();
}
function doGet(){return HtmlService.createTemplateFromFile('Index').evaluate().setTitle('บัญชีรายเดือน').setFaviconUrl('https://fonts.gstatic.com/s/e/notoemoji/latest/1f4b0/512.png').addMetaTag('apple-mobile-web-app-capable','yes').addMetaTag('mobile-web-app-capable','yes').addMetaTag('viewport','width=device-width, initial-scale=1, viewport-fit=cover');}
function include_(name){return HtmlService.createHtmlOutputFromFile(name).getContent();}
function load_(){
  const sh=db_().getSheetByName('AuditLog'), n=sh.getLastRow(),state=emptyState_(),requests=Object.create(null),history=[];
  if(n>20001)fail_('ประวัติเกินขีดจำกัดรุ่นนี้ (20,000 เหตุการณ์) โปรดสำรองและวางแผนย้ายฐานข้อมูล');
  const rows=n>1?sh.getRange(2,1,n-1,3).getValues():[];
  rows.forEach(row=>{const changes=JSON.parse(row[2]);requests[row[0]]=true;changes.forEach(c=>{if(c.value===null)delete state[c.table][c.id];else state[c.table][c.id]=c.value;});history.push({requestId:row[0],timestamp:String(row[1]),changes:changes.map(c=>({table:c.table,id:c.id,action:c.value===null?'delete':'save'}))});});
  return {state,requests,history};
}
function commit_(requestId,changes,loaded){
  if(loaded.requests[requestId])return false;
  if(db_().getSheetByName('AuditLog').getLastRow()>=20001)fail_('ถึงขีดจำกัดประวัติ กรุณาสำรองและย้ายฐานข้อมูลก่อนเพิ่มรายการ');
  const json=JSON.stringify(changes);if(json.length>45000)fail_('ข้อมูลชุดนี้ใหญ่เกินกำหนด');
  // One append is the authoritative commit. Other sheets are rebuildable projections.
  props_().setProperty('PROJECTIONS_DIRTY','1');
  db_().getSheetByName('AuditLog').appendRow([requestId,stamp_(),json]);SpreadsheetApp.flush();
  changes.forEach(c=>{if(c.value===null)delete loaded.state[c.table][c.id];else loaded.state[c.table][c.id]=c.value;});loaded.requests[requestId]=true;props_().setProperty('PROJECTIONS_DIRTY','1');return true;
}
function sync_(s){
  TABLES_.forEach(t=>{const sh=db_().getSheetByName(t);sh.getRange(2,1,Math.max(1,sh.getLastRow()-1),4).clearContent();const rows=values_(s,t).map(x=>[x.id,JSON.stringify(x),x.revision,x.updatedAt]);if(rows.length){if(sh.getMaxRows()<rows.length+1)sh.insertRowsAfter(sh.getMaxRows(),rows.length+1-sh.getMaxRows());sh.getRange(2,1,rows.length,4).setValues(rows);}});SpreadsheetApp.flush();props_().deleteProperty('PROJECTIONS_DIRTY');
}
function syncSafe_(s){try{sync_(s);}catch(e){props_().setProperty('PROJECTIONS_DIRTY','1');}}
function requestId_(id){if(typeof id!=='string'||! /^[a-zA-Z0-9_-]{8,100}$/.test(id))fail_('รหัสคำขอไม่ถูกต้อง');return id;}
function snapshotData_(l){return {state:l.state,today:today_(),history:l.history.slice(-100).reverse(),account:Session.getEffectiveUser().getEmail(),spreadsheetUrl:'https://docs.google.com/spreadsheets/d/'+props_().getProperty('SPREADSHEET_ID'),lastRecurringRun:props_().getProperty('LAST_RECURRING_RUN')||'',projectionPending:!!props_().getProperty('PROJECTIONS_DIRTY')};}
