function fail_(message) { throw new Error(message); }
function text_(v, max, required) {
  if (typeof v !== 'string' || v.length > max || (required && !v.trim())) fail_('ข้อความไม่ถูกต้องหรือยาวเกินกำหนด');
  return v.trim();
}
function money_(v, zero) {
  if (!Number.isSafeInteger(v) || v < (zero ? 0 : 1) || v > 100000000000) fail_('จำนวนเงินไม่ถูกต้อง (ต้องเป็นจำนวนสตางค์เต็ม)');
  return v;
}
function num_(v, min, max) { if (typeof v !== 'number' || !Number.isFinite(v) || v < min || v > max) fail_('ตัวเลขนอกช่วงที่รองรับ'); return v; }
