function month_(s) { if (typeof s !== 'string' || !/^20\d{2}-(0[1-9]|1[0-2])$/.test(s)) fail_('เดือนไม่ถูกต้อง'); return s; }
function dayInMonth_(m, day) { month_(m); return m+'-'+String(Math.min(day,new Date(Number(m.slice(0,4)),Number(m.slice(5)),0).getDate())).padStart(2,'0'); }
function nextMonth_(m, delta) { const d=new Date(m+'-01T00:00:00Z'); d.setUTCMonth(d.getUTCMonth()+(delta||1)); return d.toISOString().slice(0,7); }
function emptyState_() { return Object.fromEntries(TABLES_.map(t=>[t,Object.create(null)])); }
function values_(s,t) { return Object.values(s[t]); }
function actual_(s,m) { return values_(s,'Transactions').filter(t=>t.status==='actual' && (!m || t.date.slice(0,7)===m)); }
function categories_() {
  const exp=[['food','อาหาร','🍜'],['travel','เดินทาง','🚗'],['home','ที่พัก','🏠'],['shopping','ช้อปปิ้ง','🛍️'],['health','สุขภาพ','❤️'],['fun','บันเทิง','🎮'],['education','การศึกษา','📚'],['debt','ผ่อนหนี้','💳'],['give','โอนให้คนอื่น','↗️'],['saving','ออม','🐷'],['other','อื่น ๆ','📦']];
