  return exp.map((x,i)=>({id:x[0],name:x[1],icon:x[2],color:COLORS_[i],type:x[0]==='saving'?'saving':'expense',active:true})).concat(inc.map((x,i)=>({id:x[0],name:x[1],icon:x[2],color:COLORS_[i],type:'income',active:true})),[{id:'selfTransfer',name:'โอนระหว่างบัญชีตนเอง',icon:'🔁',color:'#58B8FF',type:'transfer',active:true}]);
}
function total_(rows,field) { return rows.reduce((a,x)=>a+(x[field||'amount']||0),0); }
function summary_(s,m) {
  const rows=actual_(s,m), income=total_(rows.filter(x=>x.type==='income')), expense=total_(rows.filter(x=>x.type==='expense'));
  return {income,expense,net:income-expense,saving:total_(rows.filter(x=>x.type==='saving')),transfer:total_(rows.filter(x=>x.type==='transfer')),forecast:values_(s,'Transactions').filter(x=>x.date.slice(0,7)===m && x.status==='forecast').length};
